function standardBreaths(){const extra=new Set((data?.memberPractice?.breathAccess||[]).filter(x=>x.active!==0).map(x=>x.breath_id));return Object.values(BREATHS).filter(x=>x.access==='standard'||extra.has(x.id)).filter(x=>x.selfGuided!==false)}
function renderPractice(){ensureUi();const tools=$('#memberStandardTools');tools.innerHTML=standardBreaths().map(b=>`<button class="practice-row" data-breath="${esc(b.id)}" type="button">${previewSvg(b.id)}<span class="practice-copy"><strong>${esc(b.title)}</strong><small class="practice-purpose">${esc(b.purposeShort||b.short)}</small></span><span class="practice-meta">${b.defaultMinutes} Min.</span><span class="practice-chevron">›</span></button>`).join('');tools.querySelectorAll('[data-breath]').forEach(b=>b.onclick=()=>openBreath(b.dataset.breath));const host=$('#memberAssignments'),items=data?.memberPractice?.assignments||[];host.innerHTML=items.length?'<div class="member-assignments-wrap">'+items.map(assignmentHtml).join('')+'</div>':'<div class="practice-empty">'+practiceCopy().empty+'</div>';host.querySelectorAll('[data-assignment-breath]').forEach(b=>b.onclick=()=>openBreath(b.dataset.assignmentBreath));host.querySelectorAll('[data-routine-check]').forEach(b=>b.onclick=()=>toggleCheck(b));window.BDMemberLayout?.refresh(data)}
function assignmentHtml(a){const isBreath=a.content_kind==='breath',checks=new Set((a.checks||[]).map(x=>x.date_key)),days=lastDays(a.start_date,a.end_date,7);const tracker=(a.schedule_type==='daily'||a.schedule_type==='weekly'||a.schedule_type==='repeat')?'<div class="routine-days">'+days.map(d=>'<button '+(preview?'disabled':'')+' type="button" class="routine-day '+(checks.has(d)?'done':'')+'" data-routine-check="'+a.id+'" data-date="'+d+'">'+fmtDate(d)+(checks.has(d)?' ✓':'')+'</button>').join('')+'</div>':'';return '<article class="member-assignment"><div class="member-assignment-head"><div><h3>'+esc(a.title)+'</h3><div class="member-assignment-meta">'+esc(scheduleLabel(a))+'</div></div>'+(isBreath?'<button class="assignment-start" data-assignment-breath="'+esc(a.source_id)+'" type="button">Starten</button>':'')+'</div>'+(a.description?'<p>'+esc(a.description)+'</p>':'')+(a.client_instructions?'<p>'+esc(a.client_instructions)+'</p>':'')+tracker+'</article>'}
function scheduleLabel(a){const s={once:'Einmalig',daily:'Täglich',weekly:'Mehrmals pro Woche',repeat:'Wiederkehrend'}[a.schedule_type]||'Hausübung';return [s,a.end_date?'bis '+fmtDate(a.end_date):''].filter(Boolean).join(' · ')}
function lastDays(start,end,count){const today=new Date(),out=[];for(let i=count-1;i>=0;i--){const d=new Date(today);d.setDate(today.getDate()-i);const y=d.toISOString().slice(0,10);if(start&&y<start)continue;if(end&&y>end)continue;out.push(y)}return out}
async function toggleCheck(btn){if(preview)return;const a=Number(btn.dataset.routineCheck),date=btn.dataset.date,completed=!btn.classList.contains('done');btn.disabled=true;try{const r=await fetch(API+'/member-practice/check',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token,assignmentId:a,date,completed})}),x=await r.json();if(!r.ok||!x.ok)throw Error(x.error||'Konnte nicht gespeichert werden.');await loadPracticeOnly()}catch(e){alert(e.message)}finally{btn.disabled=false}}
async function loadPracticeOnly(){const r=await fetch(API+'/package-access?token='+encodeURIComponent(token),{cache:'no-store'}),x=await r.json();if(r.ok&&x.ok){data=x;renderPractice()}}
function selectedVisual(b){return b.id==='diaphragmatic'?($('#breathVisualMode')?.value||'body'):b.visual}
function renderBreathVisuals(b){const mode=selectedVisual(b),pre=$('#breathPrevisual'),main=$('#breathVisual');if(pre){pre.innerHTML=focusVisual(b,mode);pre.dataset.kind=mode}if(main){main.innerHTML=focusVisual(b,mode);main.dataset.kind=mode}}
function openBreath(id){const b=BREATHS[id];if(!b||b.selfGuided===false)return;ensureUi();stopRun(false);const dlg=$('#breathDialog');dlg.dataset.breath=id;dlg.classList.remove('is-running');$('#breathTitle').textContent=b.title;$('#breathIntro').textContent=b.guidance||b.short;const purpose=$('#breathPurpose'),purposeTags=$('#breathPurposeTags'),purposeWrap=$('#breathPurposeWrap');if(purposeWrap)purposeWrap.open=false;if(purpose)purpose.textContent=b.purpose||b.purposeShort||b.short;if(purposeTags)purposeTags.innerHTML=(b.useTags||[]).map(x=>'<span>'+esc(x)+'</span>').join('');$('#breathVisualLabel').textContent=b.visualLabel||'';$('#breathDuration').value=String(b.defaultMinutes||3);$('#breathCountdown').textContent=String(b.defaultMinutes||3).padStart(2,'0')+':00';const choice=$('#breathVisualChoice'),mode=$('#breathVisualMode');if(choice)choice.hidden=b.id!=='diaphragmatic';if(mode&&b.id==='diaphragmatic')mode.value='body';renderBreathVisuals(b);$('#breathExplainer').innerHTML=b.id==='lion'?'<div class="explainer-quiet lion-instruction-demo">'+focusVisual(b,'lion')+'<p>'+esc(b.explainer||b.guidance||b.short)+'</p></div>':'<div class="explainer-quiet">'+previewSvg(b.id)+'<p>'+esc(b.explainer||b.guidance||b.short)+'</p></div>';$('#breathExplainToggle').checked=false;$('#breathExplainer').hidden=true;const vt=$('#breathVoiceToggle');if(vt)vt.checked=voiceEnabled;const st=$('#breathSoundscapeToggle');if(st)st.checked=soundscapeEnabled;const sv=$('#breathSoundscapeVolume');if(sv)sv.value=String(Math.round(soundscapeVolume*100));const sw=$('#breathSoundscapeVolumeWrap');if(sw)sw.hidden=!soundscapeEnabled;if(soundscapeEnabled){const sa=ensureSoundscape();if(sa.readyState===0)try{sa.load()}catch(_){}}$('#breathPhase').textContent='Bereit';$('#breathPhaseSeconds').textContent='';dlg.showModal()}
function closeBreath(){stopVoice();stopSoundscape(true);stopRun(false);$('#breathDialog')?.close()}
async function startBreath(){const dlg=$('#breathDialog'),b=BREATHS[dlg?.dataset.breath];if(!b?.phases?.length)return;stopRun(false);const total=Number($('#breathDuration').value||b.defaultMinutes||3)*60;const token=Date.now()+Math.random();run={b,index:0,total,remaining:total,phaseRemaining:0,timer:null,lastTick:Date.now(),preparing:true,token};paused=false;dlg.classList.add('is-running','is-preparing');$('#breathPause').textContent='Ⅱ';$('#breathPause').disabled=true;setCueText(voiceEnabled?'Kurzanleitung':'Bereit');$('#breathPhaseSeconds').textContent='';startSoundscape();if(voiceEnabled){await delay(520);await playVoiceSequence(b.introCues||INTRO_CUES[b.id]||['mach_es_dir_bequem'],token)}if(!run||run.token!==token)return;await delay(520);if(!run||run.token!==token)return;if(b.id==='lion'){const v=$('#breathVisual');if(v){v.classList.remove('inhale','exhale','hold','pause','topup','count');v.style.setProperty('--phase-ms','700ms');void v.offsetWidth;v.classList.add('inhale')}}setCueText('Start',true);await delay(1050);if(!run||run.token!==token)return;setCueText('',false);run.preparing=false;dlg.classList.remove('is-preparing');$('#breathPause').disabled=false;advancePhase()}
function togglePause(){if(!run||run.preparing)return;paused=!paused;$('#breathPause').textContent=paused?'▶':'Ⅱ';if(paused){stopVoice();pauseSoundscape()}else{run.lastTick=Date.now();resumeSoundscape();scheduleTick()}}
function stopRun(reset=true){if(run?.timer)clearTimeout(run.timer);stopVoice();stopSoundscape(true);run=null;paused=false;if(reset){$('#breathDialog')?.classList.remove('is-running','is-preparing')}}
function scheduleTick(){if(!run||paused||run.preparing)return;run.timer=setTimeout(tick,150)}
function advancePhase(){if(!run||run.preparing)return;const step=run.index%run.b.phases.length,phase=run.b.phases[step],cycle=Math.floor(run.index/run.b.phases.length);let seconds=phase[1];run.phaseVoiceId=null;if(run.b.id==='om_chanting'&&step===1){const v=OM_SOUND_VARIANTS[cycle%OM_SOUND_VARIANTS.length];run.phaseVoiceId=v.id;seconds=Math.max(3,v.seconds+.45)}else if(run.b.id==='lion'&&step===1){run.phaseVoiceId=HAA_SOUND_VARIANTS[cycle%HAA_SOUND_VARIANTS.length]}run.phaseRemaining=seconds;run.phaseClass=phase[2];run.phaseLabel=phase[0];run.lastTick=Date.now();applyPhase();phaseVoiceCue();scheduleTick()}
function phaseDefaultText(b,step,phaseClass,label){if(Array.isArray(b.phaseCueSets)&&b.phaseCueSets.length){const set=b.phaseCueSets[0]||[],id=set[step];if(id&&VOICE_TEXT[id])return VOICE_TEXT[id]}if(b.id==='lion')return step===0?'Atme ein':'Haaa';if(b.id==='soham')return step===0?'So':'Ham';if(b.id==='physiological_sigh'||b.id==='cyclic_sighing'){if(phaseClass==='inhale')return'Atme ein';if(phaseClass==='topup')return'Atme noch einmal kurz ein';if(phaseClass==='exhale')return'Atme langsam aus'}if(b.id==='box'){return ['Atme ein','Halte','Atme aus','Halte'][step]||label}if(phaseClass==='inhale')return'Atme ein';if(phaseClass==='exhale')return'Atme aus';if(phaseClass==='hold')return'Halte';if(phaseClass==='pause')return b.id==='mindful'?'Beobachte deinen Atem':'Pause';return label}
function applyPhase(){if(!run)return;const v=$('#breathVisual'),step=run.index%run.b.phases.length;v.classList.remove('inhale','exhale','hold','pause','topup','count');v.dataset.phaseStep=String(step);v.style.setProperty('--phase-ms',Math.max(.2,run.phaseRemaining)*1000+'ms');void v.offsetWidth;v.classList.add(run.phaseClass);let label=phaseDefaultText(run.b,step,run.phaseClass,run.phaseLabel);if(run.b.visual==='count'){const n=(run.index%10)+1;label='Atemzug '+n;const strong=v.querySelector('.focus-count strong');if(strong)strong.textContent=n;v.querySelectorAll('.count-dots i').forEach((x,i)=>x.classList.toggle('active',i===n-1))}if(run.b.visual==='soham'){const w=v.querySelector('.soham-word');if(w)w.textContent=step===0?'SO':'HAM'}setCueText(label,false);$('#breathPhaseSeconds').textContent=Math.ceil(run.phaseRemaining)+' Sek.'}
function tick(){if(!run||paused)return;const now=Date.now(),delta=(now-run.lastTick)/1000;run.lastTick=now;run.remaining=Math.max(0,run.remaining-delta);run.phaseRemaining=Math.max(0,run.phaseRemaining-delta);$('#breathCountdown').textContent=Math.floor(run.remaining/60).toString().padStart(2,'0')+':'+Math.ceil(run.remaining%60).toString().padStart(2,'0');$('#breathPhaseSeconds').textContent=Math.ceil(run.phaseRemaining)+' Sek.';if(run.remaining<=0){const dlg=$('#breathDialog');stopRun(false);dlg.classList.remove('is-running');$('#breathIntro').textContent='Fertig. Nimm noch einen Moment wahr, wie es dir jetzt geht.';return}if(run.phaseRemaining<=0){run.index++;advancePhase();return}scheduleTick()}
function boot(){ensureUi();if(window.__BD_MEMBER_DATA){data=window.__BD_MEMBER_DATA;renderPractice();return}document.addEventListener('bd:member-data',e=>{data=e.detail;renderPractice()},{once:true})}
window.BDMemberPractice={boot,breaths:BREATHS,voiceArchitecture:{enabled:true,available:VOICE_AVAILABLE,basePath:VOICE_BASE,manifest:VOICE_BASE+'manifest.json'},soundscapeArchitecture:{enabled:true,file:SOUNDSCAPE_FILE,ducking:true,domAudio:true,loopVersion:'15.12.13',naturalVoiceFlow:'15.12.15',purposeUx:true,cueTextSync:true,introPauseClasses:true,lionVisual:'15.12.16-image-overlay-demo',omVoiceLibrary:'15.12.16',haaVoiceLibrary:'15.12.16',humVoiceLibrary:'15.12.16',soundVariants:'15.12.16-recorded',omAdaptiveTiming:true}};boot();
